Q: React deleting last item in an array instead of the specified element A: <p>Use id directly inside setHeaders</p>
<pre><code>const id = +e.target.id
setHeaders(function (headers) {
  return headers.filter((x, i) =&gt; x !==  id);
});
</code></pre>
<p>And you can remove below if no longer needed</p>
<p><code>const [clickedHeader, setClickedHeader] = useState(0);</code></p>
